if (kind !== 'image' && kind !== 'video') throw new Error('Muse 网页插件目前只支持图片(image)和视频(video)');
const raw = String(args.prompt || '').trim();
if (!raw) throw new Error('缺少提示词 prompt');
let prompt = raw;
if (kind === 'image') {
  if (!/(?:image|photo|draw|paint|picture|画|图|照片|海报)/i.test(prompt)) prompt = 'Generate an image: ' + prompt;
  if (args.size) prompt += ` (aspect/size: ${args.size})`;
} else {
  const dur = args.duration ? `${args.duration}-second ` : '';
  if (!/(?:video|clip|animation|视频|短片|动画)/i.test(prompt)) prompt = `Generate a short ${dur}video: ` + prompt;
  else if (args.duration) prompt += ` (${args.duration} seconds)`;
  if (args.size) prompt += ` (aspect/size: ${args.size})`;
}

return tools.openTab('https://muse.ai/thread/new', async tabId => {
  // 唤醒后台页懒加载：对隐藏态的 IntersectionObserver 补发一次 isIntersecting:true
  await tools.evalTab(tabId, `(() => {
    if (!window.__museIoPatched && typeof window.IntersectionObserver === 'function') {
      window.__museIoPatched = true;
      const OrigIO = window.IntersectionObserver;
      window.IntersectionObserver = function (cb, opts) {
        const io = new OrigIO(cb, opts);
        const origObs = io.observe.bind(io);
        io.observe = function (el) {
          origObs(el);
          if (document.hidden && el) {
            setTimeout(() => {
              try {
                const r = el.getBoundingClientRect ? el.getBoundingClientRect() : { top: 0, left: 0, width: 300, height: 300, right: 300, bottom: 300 };
                cb([{ target: el, isIntersecting: true, intersectionRatio: 1, boundingClientRect: r, intersectionRect: r, rootBounds: r, time: performance.now() }], io);
              } catch {}
            }, 200);
          }
        };
        return io;
      };
      window.IntersectionObserver.prototype = OrigIO.prototype;
    }
  })()`, 5000, 'MAIN').catch(() => {});

  let ready = false;
  for (let i = 0; i < 20; i++) {
    ready = await tools.evalTab(tabId, `(() => {
      const ta = document.querySelector('textarea');
      return !!(ta && ta.getBoundingClientRect().width > 50 && Object.keys(ta).some(k => k.startsWith('__reactProps')));
    })()`, 5000, 'MAIN').catch(() => false);
    if (ready) break;
    await tools.sleep(400);
  }
  if (!ready) throw new Error('Muse 页面未就绪，请先在浏览器打开 https://muse.ai 确认登录状态');

  const existingImgs = await tools.evalTab(tabId, `[...document.querySelectorAll('img')].map(i => i.currentSrc || i.src || '').filter(Boolean)`, 5000, 'MAIN').catch(() => []);
  const existingSet = new Set(existingImgs || []);

  await tools.fillEditor(tabId, prompt, { selector: 'textarea', submit: false });
  const sent = await tools.evalTab(tabId, `(async () => {
    const sleep = t => new Promise(r => setTimeout(r, t));
    const ta = document.querySelector('textarea');
    if (!ta) return { ok: false, err: '找不到输入框' };
    let p = ta.parentElement;
    for (let i = 0; i < 6 && p && p.parentElement !== document.body; i++) p = p.parentElement;
    for (let k = 0; k < 20; k++) {
      const btns = [...(p || document).querySelectorAll('button,[role="button"]')].filter(b => !b.disabled && b.getAttribute('aria-disabled') !== 'true' && b.getBoundingClientRect().width > 0);
      const btn = btns.find(b => /^(?:send(?:\s+message)?|submit|发送(?:消息)?|發送(?:訊息)?|送出|提交)$/i.test((b.getAttribute('aria-label') || b.innerText || '').trim())
        || /send-button/i.test(b.getAttribute('data-testid') || ''));
      if (btn) { btn.click(); return { ok: true, aria: btn.getAttribute('aria-label') || btn.getAttribute('data-testid') }; }
      await sleep(150);
    }
    ta.focus();
    ta.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true, cancelable: true }));
    return { ok: true, via: 'enter' };
  })()`, 10000, 'MAIN');
  if (!sent?.ok) throw new Error('Muse 提交失败: ' + (sent?.err || '未知错误'));

  const maxWait = kind === 'video' ? 180000 : 90000;
  const deadline = Date.now() + maxWait;
  const wantTid = kind === 'video' ? 'hatch-chat-attachment-presentation-video' : 'hatch-chat-attachment-presentation-image';
  let foundSrc = '', lastText = '';
  while (Date.now() < deadline) {
    if (args.signal?.aborted) throw new Error('已取消');
    await tools.sleep(2000);
    const st = await tools.evalTab(tabId, `(() => {
      const att = document.querySelector('[data-testid="${wantTid}"]');
      if (att && att.scrollIntoView) try { att.scrollIntoView({ block: 'center' }); } catch {}
      const imgs = [...document.querySelectorAll('img')].filter(im => im.naturalWidth >= 256).map(im => ({
        src: im.currentSrc || im.src || '', w: im.naturalWidth, h: im.naturalHeight, isBlob: (im.currentSrc || im.src || '').startsWith('blob:'),
      }));
      const vids = [...document.querySelectorAll('video')].filter(v => (v.currentSrc || v.src) && (v.videoWidth || 0) > 120).map(v => ({
        src: v.currentSrc || v.src || '', w: v.videoWidth || 0, h: v.videoHeight || 0,
      }));
      const bubbles = [...document.querySelectorAll('div[class*="hatch-agent-bubble-bg"]')].map(b => (b.innerText || '').trim()).filter(Boolean);
      return { hasAtt: !!att, imgs, vids, text: bubbles[bubbles.length - 1] || '' };
    })()`, 10000, 'MAIN');
    if (st.text) lastText = st.text;
    if (kind === 'video') {
      if (st.vids.length) {
        st.vids.sort((a, b) => (b.w * b.h) - (a.w * a.h));
        foundSrc = st.vids[0].src;
        break;
      }
    } else {
      const fresh = (st.imgs || []).filter(x => x.src && !existingSet.has(x.src));
      if (fresh.length) {
        fresh.sort((a, b) => (b.isBlob - a.isBlob) || (b.w * b.h - a.w * a.h));
        foundSrc = fresh[0].src;
        break;
      }
    }
  }
  if (!foundSrc) throw new Error('Muse 未产出目标媒体' + (lastText ? ': ' + lastText.slice(0, 180) : '（超时）'));
  return tools.blobFromTab(tabId, foundSrc, kind === 'video' ? 'video/mp4' : 'image/webp');
}, { readyExpr: "document.querySelector('textarea')", signal: args.signal, timeout: 30000, world: 'MAIN' });

