return tools.openTab('https://muse.ai/thread/new', async tabId => {
  await tools.sleep(500);
  return tools.observeTab(tabId, !!args.detail);
}, { readyExpr: "document.querySelector('textarea')", timeout: 25000, world: 'MAIN' });
